def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my_last, opp_last = history[-1]
    opp_def = sum(1 for m, o in history if o == 'D')
    my_def = sum(1 for m, o in history if m == 'D')
    # Early: cooperate but retaliate once
    if n < 8:
        if opp_last == 'D':
            return 'D' if opp_def >= 2 else 'C'
        return 'C'
    # End game exploitation based on long-term opponent cooperativeness
    if n >= 90:
        if opp_def * 100 <= n * 20:
            return 'D'
        if opp_def * 100 >= n * 60:
            return 'D' if opp_last == 'C' else ('D' if opp_def * 100 >= n * 80 else 'C')
        return 'D' if opp_last == 'C' and n >= 95 else ('C' if opp_last == 'C' else 'D')
    # Detect persistent defector
    if n >= 10 and opp_def * 100 >= n * 75:
        return 'D'
    # Detect persistent cooperator: mostly cooperate, probe occasionally
    if opp_def * 100 <= n * 12:
        if n >= 20 and rng.random() < 0.08:
            return 'D'
        return 'C'
    # Recent window analysis
    w = 8 if n >= 8 else n
    recent = history[-w:]
    rec_opp_def = sum(1 for m, o in recent if o == 'D')
    rec_my_def = sum(1 for m, o in recent if m == 'D')
    # Strong punishment for sustained defection
    if rec_opp_def >= 5:
        if rec_my_def >= 4 and rec_opp_def >= 6:
            return 'C'
        return 'D'
    # Moderate defection in window
    if rec_opp_def >= 3:
        if opp_last == 'D':
            if rng.random() < 0.85:
                return 'D'
            return 'C'
        return 'C'
    # One or two defections recently: Tit-for-tat with forgiveness
    if rec_opp_def == 2:
        if opp_last == 'D':
            return 'D'
        return 'C'
    if rec_opp_def == 1:
        if opp_last == 'D' and my_last == 'C':
            return 'D'
        return 'C'
    # Opponent clean recently: cooperate, with rare probe when ahead
    if n >= 30 and opp_def * 100 <= n * 25 and my_def * 100 <= n * 30:
        if rng.random() < 0.06:
            return 'D'
    return 'C'
